def __repr__(self):
    if self.anisotropic:
        return '{0}(length_scale=[{1}], nu={2:.3g})'.format(self.__class__.
            __name__, ', '.join(map('{0:.3g}'.format, self.length_scale)),
            self.nu)
    else:
        return '{0}(length_scale={1:.3g}, nu={2:.3g})'.format(self.
            __class__.__name__, self.length_scale, self.nu)
